import { createHash } from "node:crypto";

const JPEG_BASE64 =
  "";

// 32x32 HEVC fixture from libheif's LGPL-3.0 test corpus:
// https://github.com/strukturag/libheif/blob/master/fuzzing/data/corpus/hevc32.heif
const HEIC_BASE64 =
  "";

export const syntheticHeic = (): Uint8Array => new Uint8Array(Buffer.from(HEIC_BASE64, "base64"));

export const syntheticJpeg = (): Uint8Array => new Uint8Array(Buffer.from(JPEG_BASE64, "base64"));

export const syntheticJpegSha256 = (): string =>
  createHash("sha256").update(syntheticJpeg()).digest("hex");
